#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
Feliz cumpleaños para la impresora térmica de CAJA de La Vara Grill.

Script suelto (no forma parte del sistema): se ejecuta desde la terminal y manda un
mensaje de cumpleaños a la impresora de caja, por el mismo camino que usa el sistema
(la impresora compartida en Windows con "LPD Print Service", puerto 515).

Uso rápido:
    python feliz_cumple_caja.py --nombre "María González"

Ya trae la IP y la cola de la impresora de caja (IP_IMPRESORA y COLA_IMPRESORA aquí abajo). Si la impresora
cambia, indícalas al ejecutar:
    python feliz_cumple_caja.py --nombre "María González" --ip 192.168.1.94 --cola POS-80C

Esos dos datos están en el sistema: Panel de configuración → Impresoras → impresora de
caja. Si cambian de forma permanente, edita IP_IMPRESORA y COLA_IMPRESORA aquí abajo.

Otras opciones:
    --mensaje 1..6        elige uno de los mensajes (por defecto uno al azar; --lista-mensajes los muestra)
    --texto "..."         escribe tu propio mensaje
    --copias 2            imprime más de una copia
    --vista tarjeta.png   NO imprime: guarda una imagen para ver cómo saldrá
    --solo-texto          versión sencilla en texto (si no hay Pillow o fuentes)
    --ancho 576           puntos de ancho: 576 = papel de 80 mm (por defecto), 384 = papel de 58 mm

Requisitos: Python 3.8+ y, para el dibujo con logo y globos, Pillow (pip install pillow).
"""
import argparse
import base64
import io
import os
import random
import socket
import sys
import textwrap
from datetime import date

# ---------------------------------------------------------------------------
# Configuración de la impresora de caja (o pásalos con --ip / --cola / --puerto)
# ---------------------------------------------------------------------------
IP_IMPRESORA = '192.168.1.94'      # PC de caja donde está compartida la impresora (la que usa el sistema)
COLA_IMPRESORA = 'POS-80C'        # Nombre compartido de la impresora en Windows
PUERTO_IMPRESORA = 515   # LPD

FIRMA = 'Con cariño, tu familia La Vara Grill'

MENSAJES = [
    'Hoy celebramos que eres parte de nuestra familia La Vara Grill. Gracias por tu esfuerzo, tu sonrisa y tus ganas de dar siempre lo mejor.\n¡Que este nuevo año de vida venga lleno de salud, alegría y mucho éxito!',
    'Cada corte que sale de nuestra parrilla lleva un poco de ti. Hoy te toca recibir lo mejor: abrazos, buenos deseos y un día para disfrutar.\n¡Que todos tus sueños se cumplan al fuego y en vara!',
    'Eres de esas personas que hacen brillar al equipo. Gracias por tu energía, tu compromiso y por contagiarnos tu buena actitud.\n¡Que este año te traiga más motivos para sonreír que clientes un sábado lleno!',
    'Un año más de experiencia, de sabor y de grandes momentos. Que Dios te bendiga, te cuide y te llene de prosperidad.\n¡Gracias por todo lo que aportas cada día!',
    '¡Hoy el protagonista eres tú! Disfruta, celebra y recibe todo nuestro cariño. Que este nuevo año te traiga muchas razones para brindar.',
    'Cada año que cumples es una nueva oportunidad para crecer, soñar y lograr cosas grandes. Sigue adelante: aquí tienes un equipo que cree en ti y te aplaude.\n¡Feliz cumpleaños!',
]

# Logo de La Vara Grill pasado a silueta negra sobre blanco (para la térmica), incrustado para que el script
# sea un solo archivo.
LOGO_PNG_B64 = ''

# ---------------------------------------------------------------------------
# ESC/POS
# ---------------------------------------------------------------------------
ESC = b'\x1b'
GS = b'\x1d'
INIT = ESC + b'@'
ALIGN_CENTER = ESC + b'a' + b'\x01'
ALIGN_LEFT = ESC + b'a' + b'\x00'
BOLD_ON = ESC + b'E' + b'\x01'
BOLD_OFF = ESC + b'E' + b'\x00'
DOUBLE_SIZE = GS + b'!' + b'\x11'
NORMAL_SIZE = GS + b'!' + b'\x00'
CUT = GS + b'V' + b'\x00'
FEED = b'\n'
CODEPAGE_1252 = ESC + b't' + b'\x10'      # WCP1252: acentos y ñ
FILAS_POR_FRANJA = 192                     # GS v 0 en franjas: algunas impresoras tienen buffer corto
UMBRAL_NEGRO = 150

FUENTES_NEGRITA = (
    r'C:\Windows\Fonts\arialbd.ttf',
    '/usr/share/fonts/truetype/liberation/LiberationSans-Bold.ttf',
    '/usr/share/fonts/liberation/LiberationSans-Bold.ttf',
    '/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf',
)
FUENTES_REGULAR = (
    r'C:\Windows\Fonts\arial.ttf',
    '/usr/share/fonts/truetype/liberation/LiberationSans-Regular.ttf',
    '/usr/share/fonts/liberation/LiberationSans-Regular.ttf',
    '/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf',
)
FUENTES_MANUSCRITA = (
    r'C:\Windows\Fonts\segoescb.ttf',      # Segoe Script Bold
    r'C:\Windows\Fonts\segoesc.ttf',
    r'C:\Windows\Fonts\BRUSHSCI.TTF',
    r'C:\Windows\Fonts\LHANDW.TTF',
)


# ---------------------------------------------------------------------------
# Envío por LPD (RFC 1179) — el mismo protocolo que usa el sistema
# ---------------------------------------------------------------------------
LPD_ORIGEN = 'varagrill'
LPD_TIMEOUT = 15


class LpdError(Exception):
    pass


def _recibir_ok(sock, etapa, cola=None):
    try:
        ack = sock.recv(1)
    except socket.timeout as exc:
        raise LpdError(f'Tiempo de espera agotado esperando confirmación en la etapa "{etapa}".') from exc
    except OSError as exc:
        raise LpdError(f'Error de red en la etapa "{etapa}": {exc}.') from exc
    if not ack:
        raise LpdError(f'La impresora cerró la conexión sin responder en la etapa "{etapa}".')
    if ack != b'\x00':
        if etapa == 'seleccionar cola' and ack == b'\x01':
            raise LpdError(
                f'La impresora no reconoce la cola "{cola}". Debe coincidir exactamente con el nombre '
                'compartido de la impresora en Windows (Panel de configuración → Impresoras).'
            )
        raise LpdError(f'La impresora rechazó la etapa "{etapa}" (código {ack[0]}).')


def _enviar(sock, datos, etapa, cola=None):
    try:
        sock.sendall(datos)
    except socket.timeout as exc:
        raise LpdError(f'Tiempo de espera agotado enviando la etapa "{etapa}".') from exc
    except OSError as exc:
        raise LpdError(f'Error de red enviando la etapa "{etapa}": {exc}.') from exc
    _recibir_ok(sock, etapa, cola=cola)


def enviar_lpd(host, puerto, cola, datos, job_id=1, usuario='varagrill', nombre_trabajo='Cumpleanos'):
    sufijo = f'{job_id % 1000:03d}{LPD_ORIGEN}'
    archivo_datos = f'dfA{sufijo}'
    archivo_control = f'cfA{sufijo}'
    control = (
        f'H{LPD_ORIGEN}\nP{usuario}\nJ{nombre_trabajo}\nl{archivo_datos}\nU{archivo_datos}\nN{nombre_trabajo}\n'
    ).encode('ascii', errors='replace')
    try:
        conexion = socket.create_connection((host, puerto), timeout=LPD_TIMEOUT)
    except socket.timeout as exc:
        raise LpdError(f'Tiempo de espera agotado conectando a {host}:{puerto}.') from exc
    except OSError as exc:
        raise LpdError(f'No se pudo conectar a {host}:{puerto}: {exc}.') from exc
    with conexion as sock:
        sock.settimeout(LPD_TIMEOUT)
        _enviar(sock, b'\x02' + cola.encode('ascii', errors='replace') + b'\n', 'seleccionar cola', cola=cola)
        _enviar(sock, f'\x02{len(control)} {archivo_control}\n'.encode('ascii'), 'anunciar archivo de control')
        _enviar(sock, control + b'\x00', 'enviar archivo de control')
        _enviar(sock, f'\x03{len(datos)} {archivo_datos}\n'.encode('ascii'), 'anunciar archivo de datos')
        _enviar(sock, datos + b'\x00', 'enviar archivo de datos')


# ---------------------------------------------------------------------------
# Tarjeta gráfica (Pillow)
# ---------------------------------------------------------------------------
def _ruta_fuente(opciones):
    for ruta in opciones:
        if os.path.exists(ruta):
            return ruta
    return None


def dibujar_tarjeta(nombre, mensaje, ancho=576):
    """Devuelve una imagen 'L' (255 = blanco) con la tarjeta de cumpleaños."""
    from PIL import Image, ImageDraw, ImageFont

    k = ancho / 576.0                       # todo está diseñado para 576 puntos (80 mm)
    margen = round(14 * k)
    util = ancho - 2 * margen

    ruta_negrita = _ruta_fuente(FUENTES_NEGRITA)
    ruta_regular = _ruta_fuente(FUENTES_REGULAR)
    ruta_manuscrita = _ruta_fuente(FUENTES_MANUSCRITA) or ruta_negrita
    if not ruta_negrita or not ruta_regular:
        raise RuntimeError('No se encontraron fuentes del sistema para dibujar la tarjeta.')

    def fuente(ruta, tamano):
        return ImageFont.truetype(ruta, max(8, round(tamano * k)))

    def envolver(texto, fnt, maximo):
        lineas = []
        for parrafo in str(texto).split('\n'):
            actual = ''
            for palabra in parrafo.split(' '):
                prueba = palabra if not actual else f'{actual} {palabra}'
                if fnt.getlength(prueba) <= maximo or not actual:
                    actual = prueba
                else:
                    lineas.append(actual)
                    actual = palabra
            lineas.append(actual)
        return lineas or ['']

    franjas = []

    def espacio(alto):
        franjas.append(Image.new('L', (ancho, max(1, round(alto * k))), 255))

    def ajustar(ruta, lineas, tamano, maximo):
        """La fuente más grande (hasta `tamano`) con la que todas las líneas caben en `maximo` puntos."""
        while tamano > 14:
            fnt = fuente(ruta, tamano)
            if max(fnt.getlength(l) for l in lineas) <= maximo:
                return fnt
            tamano -= 3
        return fuente(ruta, 14)

    def texto_centrado(lineas, fnt, interlineado=6, relleno=0, fondo=255):
        ascenso, descenso = fnt.getmetrics()
        alto_linea = ascenso + descenso + round(interlineado * k)
        franja = Image.new('L', (ancho, alto_linea * (len(lineas) - 1) + ascenso + descenso + 4), fondo)
        d = ImageDraw.Draw(franja)
        y = 2
        for linea in lineas:
            largo = fnt.getlength(linea)
            d.text(((ancho - largo) / 2, y), linea, font=fnt, fill=relleno)
            y += alto_linea
        franjas.append(franja)

    def estrella(d, cx, cy, r, relleno=0):
        import math
        puntos = []
        for i in range(10):
            radio = r if i % 2 == 0 else r * 0.42
            ang = -math.pi / 2 + i * math.pi / 5
            puntos.append((cx + radio * math.cos(ang), cy + radio * math.sin(ang)))
        d.polygon(puntos, fill=relleno)

    def globos(alto=150):
        """Fila de globos con hilos y un poco de confeti."""
        alto = round(alto * k)
        franja = Image.new('L', (ancho, alto), 255)
        d = ImageDraw.Draw(franja)
        n = 7
        paso = (ancho - 2 * margen) / n
        for i in range(n):
            cx = margen + paso * (i + 0.5)
            ry = (38 if i % 2 == 0 else 32) * k
            rx = ry * 0.82
            cy = (ry + 8 * k) + (0 if i % 2 == 0 else 14 * k)
            relleno = 0 if i % 3 != 1 else 120       # algunos globos en gris (se imprime tramado/claro)
            if relleno == 0:
                d.ellipse((cx - rx, cy - ry, cx + rx, cy + ry), fill=0)
                d.ellipse((cx - rx * 0.55, cy - ry * 0.62, cx - rx * 0.2, cy - ry * 0.18), fill=255)
            else:
                d.ellipse((cx - rx, cy - ry, cx + rx, cy + ry), outline=0, width=max(2, round(4 * k)))
                d.ellipse((cx - rx * 0.55, cy - ry * 0.62, cx - rx * 0.2, cy - ry * 0.18), outline=0, width=max(1, round(2 * k)))
            d.polygon([(cx - 5 * k, cy + ry), (cx + 5 * k, cy + ry), (cx, cy + ry + 9 * k)], fill=0)
            # hilo ondulado
            y0 = cy + ry + 9 * k
            x = cx
            for j in range(6):
                x2 = cx + (6 * k if j % 2 == 0 else -6 * k)
                d.line((x, y0 + j * 7 * k, x2, y0 + (j + 1) * 7 * k), fill=0, width=max(1, round(2 * k)))
                x = x2
        franjas.append(franja)

    def linea_de_estrellas(alto=26):
        alto = round(alto * k)
        franja = Image.new('L', (ancho, alto), 255)
        d = ImageDraw.Draw(franja)
        cy = alto / 2
        n = 9
        paso = (ancho - 2 * margen) / n
        for i in range(n):
            cx = margen + paso * (i + 0.5)
            if i % 2 == 0:
                estrella(d, cx, cy, 10 * k)
            else:
                d.ellipse((cx - 4 * k, cy - 4 * k, cx + 4 * k, cy + 4 * k), fill=0)
        franjas.append(franja)

    def confeti(alto=24):
        franja = Image.new('L', (ancho, round(alto * k)), 255)
        d = ImageDraw.Draw(franja)
        rnd = random.Random(7)
        for _ in range(26):
            x = rnd.uniform(margen, ancho - margen)
            y = rnd.uniform(3 * k, franja.height - 3 * k)
            tipo = rnd.randint(0, 2)
            if tipo == 0:
                d.ellipse((x - 3 * k, y - 3 * k, x + 3 * k, y + 3 * k), fill=0)
            elif tipo == 1:
                d.line((x - 6 * k, y - 2 * k, x + 6 * k, y + 2 * k), fill=0, width=max(2, round(3 * k)))
            else:
                estrella(d, x, y, 5 * k)
        franjas.append(franja)

    # --- logo ---------------------------------------------------------------
    espacio(6)
    try:
        logo = Image.open(io.BytesIO(base64.b64decode(LOGO_PNG_B64))).convert('RGBA')
        fondo = Image.new('RGBA', logo.size, (255, 255, 255, 255))
        logo = Image.alpha_composite(fondo, logo).convert('L')
        logo = logo.point(lambda v: 0 if v < 190 else 255)                 # negro firme para la térmica
        ancho_logo = round(320 * k)
        logo = logo.resize((ancho_logo, round(logo.height * ancho_logo / logo.width)), Image.LANCZOS)
        franja = Image.new('L', (ancho, logo.height + 6), 255)
        franja.paste(logo, ((ancho - logo.width) // 2, 3))
        franjas.append(franja)
    except Exception:
        texto_centrado(['LA VARA', 'GRILL'], fuente(ruta_negrita, 54))

    espacio(2)
    globos()
    confeti(22)

    # --- título --------------------------------------------------------------
    titulo = ['¡Feliz', 'Cumpleaños!']
    texto_centrado(titulo, ajustar(ruta_manuscrita, titulo, 92, util - round(8 * k)), interlineado=-22)
    espacio(10)

    # cinta negra con texto en blanco
    fnt_cinta = fuente(ruta_negrita, 30)
    cinta_texto = 'PARA TI, CON CARIÑO'
    alto_cinta = round(52 * k)
    cinta = Image.new('L', (ancho, alto_cinta + 4), 255)
    d = ImageDraw.Draw(cinta)
    d.rounded_rectangle((margen, 2, ancho - margen, 2 + alto_cinta), radius=round(10 * k), fill=0)
    largo = fnt_cinta.getlength(cinta_texto)
    d.text(((ancho - largo) / 2, 2 + (alto_cinta - fnt_cinta.size) / 2 - 2 * k), cinta_texto, font=fnt_cinta, fill=255)
    franjas.append(cinta)
    espacio(12)

    # --- nombre (se achica solo si es largo) ---------------------------------
    nombre = ' '.join(str(nombre).split()).upper() or 'FELICIDADES'
    tamano = 80
    while True:
        fnt_nombre = fuente(ruta_negrita, tamano)
        lineas = envolver(nombre, fnt_nombre, util)
        if (len(lineas) <= 2 and max(fnt_nombre.getlength(l) for l in lineas) <= util) or tamano <= 30:
            break
        tamano -= 4
    texto_centrado(lineas, fnt_nombre, interlineado=4)
    espacio(8)
    linea_de_estrellas()
    espacio(8)

    # --- mensaje ---------------------------------------------------------------
    fnt_mensaje = fuente(ruta_regular, 30)
    texto_centrado(envolver(mensaje, fnt_mensaje, util - round(10 * k)), fnt_mensaje, interlineado=8)
    espacio(14)

    # --- firma y fecha ----------------------------------------------------------
    fnt_firma = ajustar(ruta_manuscrita, [FIRMA], 44, util - round(8 * k))
    texto_centrado(envolver(FIRMA, fnt_firma, util), fnt_firma, interlineado=4)
    espacio(4)
    meses = ['enero', 'febrero', 'marzo', 'abril', 'mayo', 'junio', 'julio', 'agosto', 'septiembre', 'octubre', 'noviembre', 'diciembre']
    hoy = date.today()
    texto_centrado([f'{hoy.day} de {meses[hoy.month - 1]} de {hoy.year}'], fuente(ruta_regular, 24))
    espacio(8)
    confeti(26)
    linea_de_estrellas()
    espacio(6)

    alto_total = sum(f.height for f in franjas) + 2 * margen
    lienzo = Image.new('L', (ancho, alto_total), 255)
    y = margen
    for franja in franjas:
        lienzo.paste(franja, (0, y))
        y += franja.height
    return lienzo


def imagen_a_escpos(imagen):
    """GS v 0 (raster) en franjas, con avance de papel y corte al final."""
    from PIL import Image

    ancho, alto = imagen.size
    if ancho % 8:
        raise ValueError('El ancho de la imagen debe ser múltiplo de 8.')
    bits = imagen.point(lambda v: 255 if v < UMBRAL_NEGRO else 0).convert('1', dither=Image.Dither.NONE)
    ancho_bytes = ancho // 8
    out = bytearray()
    out += INIT + ALIGN_CENTER
    for inicio in range(0, alto, FILAS_POR_FRANJA):
        fin = min(inicio + FILAS_POR_FRANJA, alto)
        franja = bits.crop((0, inicio, ancho, fin)).tobytes()
        out += GS + b'v0' + b'\x00' + ancho_bytes.to_bytes(2, 'little') + (fin - inicio).to_bytes(2, 'little') + franja
    out += ALIGN_LEFT + FEED * 4 + CUT
    return bytes(out)


# ---------------------------------------------------------------------------
# Versión sencilla en texto (si no hay Pillow o fuentes)
# ---------------------------------------------------------------------------
def tarjeta_en_texto(nombre, mensaje, columnas=32):
    def txt(valor):
        return str(valor).encode('cp1252', errors='replace')

    def centrado(valor, ancho=columnas):
        return [linea.center(ancho) for linea in textwrap.wrap(valor, ancho) or ['']]

    out = bytearray(INIT + CODEPAGE_1252 + ALIGN_CENTER)
    out += txt('*' * columnas) + FEED
    out += BOLD_ON + DOUBLE_SIZE + txt('FELIZ') + FEED + txt('CUMPLEAÑOS!') + FEED + NORMAL_SIZE + BOLD_OFF
    out += txt('*' * columnas) + FEED + FEED
    out += BOLD_ON + txt('PARA TI, CON CARIÑO') + FEED + BOLD_OFF
    for linea in textwrap.wrap(' '.join(str(nombre).split()).upper(), columnas // 2) or ['']:
        out += BOLD_ON + DOUBLE_SIZE + txt(linea) + FEED + NORMAL_SIZE + BOLD_OFF
    out += FEED
    for parrafo in str(mensaje).split('\n'):
        for linea in textwrap.wrap(parrafo, columnas) or ['']:
            out += txt(linea) + FEED
    out += FEED + txt(FIRMA) + FEED + txt('*' * columnas) + FEED
    out += ALIGN_LEFT + FEED * 4 + CUT
    return bytes(out)


# ---------------------------------------------------------------------------
def construir(args, nombre, mensaje):
    """Devuelve (bytes_para_la_impresora, imagen_o_None, aviso)."""
    if not args.solo_texto:
        try:
            imagen = dibujar_tarjeta(nombre, mensaje, ancho=args.ancho)
            return imagen_a_escpos(imagen), imagen, ''
        except Exception as exc:                       # sin Pillow o sin fuentes: texto
            aviso = f'No se pudo dibujar la tarjeta gráfica ({exc}); se usa la versión en texto.'
            return tarjeta_en_texto(nombre, mensaje, 32 if args.ancho < 500 else 42), None, aviso
    return tarjeta_en_texto(nombre, mensaje, 32 if args.ancho < 500 else 42), None, ''


def main(argv=None):
    for flujo in (sys.stdout, sys.stderr):
        try:
            flujo.reconfigure(encoding='utf-8', errors='replace')
        except Exception:
            pass
    ap = argparse.ArgumentParser(description='Imprime un feliz cumpleaños en la impresora térmica de caja.')
    ap.add_argument('--nombre', help='Nombre del empleado que cumple años')
    ap.add_argument('--mensaje', type=int, help='Número de mensaje (1 a %d)' % len(MENSAJES))
    ap.add_argument('--texto', help='Tu propio mensaje (reemplaza a los predefinidos)')
    ap.add_argument('--copias', type=int, default=1)
    ap.add_argument('--ip', default=IP_IMPRESORA)
    ap.add_argument('--cola', default=COLA_IMPRESORA)
    ap.add_argument('--puerto', type=int, default=PUERTO_IMPRESORA)
    ap.add_argument('--ancho', type=int, default=576, help='Puntos de ancho: 576 (80 mm) o 384 (58 mm)')
    ap.add_argument('--vista', metavar='ARCHIVO.png', help='No imprime: guarda una imagen de la tarjeta')
    ap.add_argument('--solo-texto', action='store_true', help='Versión sencilla en texto')
    ap.add_argument('--lista-mensajes', action='store_true')
    args = ap.parse_args(argv)

    if args.lista_mensajes:
        for i, m in enumerate(MENSAJES, 1):
            print(f'{i}. {m}\n')
        return 0
    if args.ancho % 8:
        ap.error('--ancho debe ser múltiplo de 8 (576 o 384).')

    nombre = args.nombre
    if not nombre:
        nombre = input('Nombre del empleado: ').strip()
    if not nombre:
        print('Falta el nombre del empleado.')
        return 1

    if args.texto:
        mensaje = args.texto.replace('\\n', '\n')
    elif args.mensaje:
        if not 1 <= args.mensaje <= len(MENSAJES):
            ap.error(f'--mensaje va de 1 a {len(MENSAJES)}.')
        mensaje = MENSAJES[args.mensaje - 1]
    else:
        mensaje = random.choice(MENSAJES)

    datos, imagen, aviso = construir(args, nombre, mensaje)
    if aviso:
        print(aviso)

    if args.vista:
        if imagen is None:
            print('No hay imagen para guardar (falta Pillow o se pidió --solo-texto).')
            return 1
        imagen.save(args.vista)
        print(f'Vista guardada en {args.vista} ({imagen.width}x{imagen.height} puntos). No se imprimió nada.')
        return 0

    if not args.ip or not args.cola:
        print(
            'Falta la impresora. Indica su IP y su cola:  --ip 192.168.x.x --cola NOMBRE\n'
            '(los ves en el sistema: Panel de configuración → Impresoras → impresora de caja),\n'
            'o escríbelos en IP_IMPRESORA y COLA_IMPRESORA al inicio de este archivo.'
        )
        return 1

    try:
        for numero in range(max(1, args.copias)):
            enviar_lpd(args.ip, args.puerto, args.cola, datos, job_id=numero + 1, nombre_trabajo='Cumpleanos')
    except LpdError as exc:
        print(f'No se pudo imprimir: {exc}')
        return 2
    print(f'Listo: feliz cumpleaños para {nombre} enviado a la impresora ({args.ip}, cola "{args.cola}").')
    return 0


if __name__ == '__main__':
    sys.exit(main())
